local MortarMaker = {}
local PRODUCTS = {
    small_mortar = { name = "Majhen minomet", ironCost = 3, woodCost = 2, gunpowderCost = 2, time = 5, cost = 280, attack = 45, range = 150, durability = 30, description = "Majhen minomet za lokostrelsko pehoto." },
    bronze_mortar = { name = "Bronast minomet", bronzeCost = 4, ironCost = 2, woodCost = 3, gunpowderCost = 3, time = 8, cost = 700, attack = 70, range = 180, durability = 45, prestige = 3, description = "Bronast minomet z visoko trajnostjo." },
    iron_mortar = { name = "Železen minomet", ironCost = 6, woodCost = 4, gunpowderCost = 4, time = 12, cost = 1500, attack = 100, range = 220, durability = 65, prestige = 6, happiness = 1, description = "Železen minomet za utrdbe." },
    heavy_mortar = { name = "Težki minomet", ironCost = 8, bronzeCost = 4, woodCost = 5, gunpowderCost = 5, time = 16, cost = 3000, attack = 145, range = 260, durability = 85, prestige = 12, happiness = 2, description = "Težki minomet za močne eksplozivne granate." },
    silver_decorated_mortar = { name = "Srebrno okrašen minomet", ironCost = 8, bronzeCost = 4, silverCost = 2, woodCost = 5, gunpowderCost = 5, time = 20, cost = 5800, attack = 200, range = 300, durability = 105, prestige = 22, happiness = 4, description = "Minomet s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_mortar = { name = "Kraljevski veliki minomet", ironCost = 12, bronzeCost = 8, steelCost = 4, goldCost = 3, silverCost = 2, woodCost = 8, gunpowderCost = 7, jewelCost = 1, time = 27, cost = 12500, attack = 290, range = 400, durability = 155, prestige = 60, happiness = 12, description = "Veliki kraljevski minomet z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Minometna delavnica", cost = { gold = 550, wood = 200, stone = 250 }, upkeep = 13, qualityBonus = 5 },
    foundry = { name = "Livarna minometov", cost = { gold = 2000, wood = 350, stone = 600, iron = 12, bronze = 8 }, upkeep = 45, qualityBonus = 18 },
    boring_room = { name = "Vrtalnica", cost = { gold = 4500, wood = 500, stone = 900, silver = 50, steel = 8 }, upkeep = 90, qualityBonus = 30 },
    royal_mortar_atelier = { name = "Kraljevski atelje minometov", cost = { gold = 18000, wood = 1200, stone = 2000, gold = 250, jewel = 25 }, upkeep = 380, qualityBonus = 55, prestigeBonus = 55 },
}
MortarMaker.ironStock = 14; MortarMaker.bronzeStock = 14; MortarMaker.steelStock = 10; MortarMaker.woodStock = 16; MortarMaker.silverStock = 8; MortarMaker.goldStock = 6; MortarMaker.jewelStock = 6; MortarMaker.gunpowderStock = 12
MortarMaker.productStock = {}; MortarMaker.buildings = {}; MortarMaker.maker = nil; MortarMaker.activeMaking = {}; MortarMaker.totalProducts = 0; MortarMaker.dayTimer = 0
function MortarMaker.init() MortarMaker.ironStock=14; MortarMaker.bronzeStock=14; MortarMaker.steelStock=10; MortarMaker.woodStock=16; MortarMaker.silverStock=8; MortarMaker.goldStock=6; MortarMaker.jewelStock=6; MortarMaker.gunpowderStock=12; MortarMaker.productStock={}; MortarMaker.buildings={}; MortarMaker.maker=nil; MortarMaker.activeMaking={}; MortarMaker.totalProducts=0; MortarMaker.dayTimer=0; print("[MortarMaker] Royal Mortar Maker System initialized (6 products, 4 buildings)") end
function MortarMaker.hireMaker(n,s) s=s or math.random(55,95); local c=720+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MortarMaker.maker={name=n or ("Minometar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Minometar najet: %s (spretnost: %d)",MortarMaker.maker.name,s),"success") end; return true end
function MortarMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MortarMaker.build(id) local ok,e=MortarMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MortarMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MortarMaker.getQualityBonus() local b=0; for _,bd in ipairs(MortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MortarMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MortarMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MortarMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.steelCost and MortarMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and MortarMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and MortarMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MortarMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MortarMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.gunpowderCost and MortarMaker.gunpowderStock<(d.gunpowderCost or 0) then return false,"Premalo smodnika" end; if #MortarMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MortarMaker.maker then return false,"Potreben minometar" end; return true end
function MortarMaker.make(pt,qty) qty=qty or 1; local ok,e=MortarMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MortarMaker.ironStock=MortarMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MortarMaker.bronzeStock=MortarMaker.bronzeStock-d.bronzeCost*qty end; if d.steelCost then MortarMaker.steelStock=MortarMaker.steelStock-d.steelCost*qty end; if d.woodCost then MortarMaker.woodStock=MortarMaker.woodStock-d.woodCost*qty end; if d.silverCost then MortarMaker.silverStock=MortarMaker.silverStock-d.silverCost*qty end; if d.goldCost then MortarMaker.goldStock=MortarMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MortarMaker.jewelStock=MortarMaker.jewelStock-d.jewelCost*qty end; if d.gunpowderCost then MortarMaker.gunpowderStock=MortarMaker.gunpowderStock-d.gunpowderCost*qty end; local t=d.time; if MortarMaker.maker then t=math.max(1,t-math.floor(MortarMaker.maker.skill/12)) end; table.insert(MortarMaker.activeMaking,{id="mortar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MortarMaker.completeMaking(m) local q=1.0+(MortarMaker.getQualityBonus()/100); if MortarMaker.maker then q=q+(MortarMaker.maker.skill/150) end; q=math.min(2.5,q); MortarMaker.productStock[m.productType]=(MortarMaker.productStock[m.productType] or 0)+m.quantity; MortarMaker.totalProducts=MortarMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MortarMaker.maker then MortarMaker.maker.itemsMade=MortarMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MortarMaker.maker.skill=math.min(100,MortarMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Minomet izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"mortar.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function MortarMaker.update(dt) if not _G.state then return end; MortarMaker.dayTimer=MortarMaker.dayTimer+dt; if MortarMaker.dayTimer>=30 then MortarMaker.dayTimer=0; for i=#MortarMaker.activeMaking,1,-1 do local m=MortarMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MortarMaker.completeMaking(m); table.remove(MortarMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MortarMaker.maker then tu=tu+24 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MortarMaker.getStats() return {ironStock=MortarMaker.ironStock,bronzeStock=MortarMaker.bronzeStock,steelStock=MortarMaker.steelStock,woodStock=MortarMaker.woodStock,silverStock=MortarMaker.silverStock,goldStock=MortarMaker.goldStock,jewelStock=MortarMaker.jewelStock,gunpowderStock=MortarMaker.gunpowderStock,productStock=MortarMaker.productStock,numBuildings=#MortarMaker.buildings,hasMaker=MortarMaker.maker~=nil,makerName=MortarMaker.maker and MortarMaker.maker.name or "—",makerSkill=MortarMaker.maker and MortarMaker.maker.skill or 0,activeMaking=#MortarMaker.activeMaking,totalProducts=MortarMaker.totalProducts} end
return MortarMaker
